KIND_FUNCTION = "function"
KIND_RECEIVE = "receive"
KIND_FALLBACK = "fallback"

_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


# ---- 不可变注册表 ----------------------------------------------------------


@dataclass(frozen=True)
class ContractCallRegistry:
    """不可变合约调用注册表（function 按 ABI 声明顺序保存）。

