    def data(self) -> bytes:
        """函数为参数区，fallback 为完整 calldata，receive 为 ``b""``。"""
        return self._data

    @property
    def calldata(self) -> bytes:
        """完整 calldata（与结果值本身相等的 bytes）。"""
        return bytes(self)

    @property
    def calldata_hex(self) -> str:
        """``"0x"`` 前缀的完整 calldata 十六进制字符串。"""
        return "0x" + self.hex()

