    """receive / fallback 条目不接受 inputs（缺省或空数组视为无）。"""
    inputs = entry.get("inputs", ())
    if not isinstance(inputs, (list, tuple)) or inputs:
        raise _entry_invalid(f"{entry_type} 条目不接受 inputs，得到 {inputs!r}")


